<?php get_header(); ?><main id="main" class="content-area wrap"><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><article <?php post_class(); ?>><h1><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h1><?php if ( is_singular() ) { the_content(); wp_link_pages(); if ( comments_open() || get_comments_number() ) comments_template(); } else { the_excerpt(); } ?></article><?php endwhile; the_posts_navigation(); else : ?><h1>Nothing found</h1><?php get_search_form(); endif; ?></main><?php get_footer(); ?>
